-- 상품사진(S3) → SKU image_url 주입. 파일명 No = 마스터리스트 No.
-- 매칭키: 단지(complex)+품목(product_name)+규격(spec) — id 무관하게 로컬/운영 동일 적용.
-- S3 버킷은 public-read, URL은 절대경로라 프론트에서 직접 로드됨.
SET NAMES utf8mb4;

UPDATE skus s JOIN stock st ON st.sku_id=s.id JOIN storage_locations sl ON sl.id=st.storage_location_id JOIN complexes cx ON cx.id=sl.complex_id SET s.image_url='https://dwe-on-mpark.s3.ap-northeast-2.amazonaws.com/mpark/stock/image/product/149.jpg' WHERE cx.name='타워' AND s.product_name='V벨트' AND s.spec='B-84/DONGIL';
